import { intlLocale } from "../i18n";
import { COUNTRY_CODES } from "./countryCodes";

/*
 * Country names come from the core in English (GeoNames). `countryCodes.ts`
 * maps each to its ISO code — generated by `scripts/gen-countries.mjs` from
 * `src-tauri/resources/geo/countries.tsv` — and `Intl.DisplayNames` supplies the
 * name in the interface language. The English is still the data: filters, ids
 * and what goes back to the core keep using it; this only changes what is drawn.
 */

const displayNames = new Map<string, Intl.DisplayNames | null>();

function namesFor(locale: string): Intl.DisplayNames | null {
  let d = displayNames.get(locale);
  if (d === undefined) {
    try {
      d = new Intl.DisplayNames([locale], { type: "region" });
    } catch {
      d = null;
    }
    displayNames.set(locale, d);
  }
  return d;
}

/** A country's name in the interface language; the English when it is not one we can place. */
export function countryName(english: string): string {
  const code = COUNTRY_CODES[english];
  if (!code) return english;
  try {
    return namesFor(intlLocale())?.of(code) ?? english;
  } catch {
    return english;
  }
}

/**
 * A full place name ("Edinburgh, United Kingdom") with its trailing English
 * country swapped for the localised one. Pass the place's `country` when it is
 * known; without it, whatever follows the last comma is taken to be the country
 * if it is one. A name that does not end in a country is returned as it is.
 */
export function localPlaceName(name: string, country?: string | null): string {
  if (country) {
    const suffix = `, ${country}`;
    if (!name.toLowerCase().endsWith(suffix.toLowerCase())) return name;
    return name.slice(0, -suffix.length) + `, ${countryName(country)}`;
  }
  const at = name.lastIndexOf(", ");
  if (at < 0) return name;
  const tail = name.slice(at + 2);
  return tail in COUNTRY_CODES ? `${name.slice(0, at)}, ${countryName(tail)}` : name;
}
